from pathlib import Path


def replace(path: str, old: str, new: str) -> None:
    file = Path(path)
    text = file.read_text()
    if old not in text:
        raise RuntimeError(f"missing fragment in {path}: {old[:100]!r}")
    file.write_text(text.replace(old, new, 1))


